CREATE EXTENSION IF NOT EXISTS vector;
DO $$ BEGIN CREATE TYPE event_status AS ENUM ('DISCOVERED','DEVELOPING','CONFIRMED','ESCALATING','DE_ESCALATING','ONGOING','RESOLVED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE claim_type AS ENUM ('OCCURRENCE','ATTRIBUTION','LOCATION','TIME','QUANTITATIVE','INTENT','STATUS','RESPONSE','CONSEQUENCE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE confidence_level AS ENUM ('HIGH','MEDIUM','LOW','CONTESTED','UNVERIFIED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE evidence_type AS ENUM ('OFFICIAL_STATEMENT','SATELLITE_IMAGERY','GEOSPATIAL_DATA','VIDEO','PHOTOGRAPH','DOCUMENT','FLIGHT_TRACKING','SHIP_TRACKING','RADAR_DATA','EYEWITNESS','PHYSICAL_EVIDENCE','OPEN_SOURCE_ANALYSIS','OTHER'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, base_url text, tier smallint NOT NULL CHECK(tier BETWEEN 1 AND 4), source_type text NOT NULL DEFAULT 'PUBLISHER', enabled boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source_feeds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources ON DELETE CASCADE, url text NOT NULL UNIQUE, category text NOT NULL DEFAULT 'GLOBAL', language text, enabled boolean NOT NULL DEFAULT true, last_success_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, summary text, status event_status NOT NULL DEFAULT 'DISCOVERED', importance jsonb NOT NULL DEFAULT '{}', importance_level smallint NOT NULL DEFAULT 0 CHECK(importance_level BETWEEN 0 AND 5), india_relevance smallint NOT NULL DEFAULT 0 CHECK(india_relevance BETWEEN 0 AND 4), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), knowledge_version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_thread_id uuid NOT NULL REFERENCES event_threads ON DELETE CASCADE, title text NOT NULL, summary text, occurred_at timestamptz, fingerprint jsonb NOT NULL DEFAULT '{}', importance jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS incidents_event_time_idx ON incidents(event_thread_id, occurred_at DESC);
CREATE TABLE IF NOT EXISTS event_relationships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_event_id uuid NOT NULL REFERENCES event_threads ON DELETE CASCADE, to_event_id uuid NOT NULL REFERENCES event_threads ON DELETE CASCADE, relation text NOT NULL CHECK(relation IN ('RELATED_TO','CAUSED_BY','RESPONDED_TO','ESCALATED_FROM','INFLUENCED_BY','DEPENDENT_ON')), explanation text, UNIQUE(from_event_id,to_event_id,relation), CHECK(from_event_id<>to_event_id));
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources, canonical_url text NOT NULL UNIQUE, title text NOT NULL, author text, language text, document_type text NOT NULL DEFAULT 'ARTICLE', published_at timestamptz, collected_at timestamptz NOT NULL DEFAULT now(), content_hash text NOT NULL, excerpt text, citation_lineage jsonb NOT NULL DEFAULT '[]', incident_id uuid REFERENCES incidents ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS documents_hash_idx ON documents(content_hash);
CREATE TABLE IF NOT EXISTS claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents ON DELETE CASCADE, statement text NOT NULL, type claim_type NOT NULL, status text NOT NULL DEFAULT 'UNVERIFIED', confidence confidence_level NOT NULL DEFAULT 'UNVERIFIED', confidence_explanation text NOT NULL DEFAULT 'Insufficient independent evidence.', intent_label text CHECK(intent_label IS NULL OR intent_label IN ('REPORTED_INTENT','INFERENCE','SPECULATION','UNKNOWN')), valid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), canonical_key text, UNIQUE(incident_id,canonical_key));
CREATE TABLE IF NOT EXISTS claim_sources(claim_id uuid NOT NULL REFERENCES claims ON DELETE CASCADE, document_id uuid NOT NULL REFERENCES documents ON DELETE CASCADE, provenance_note text, PRIMARY KEY(claim_id,document_id));
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type evidence_type NOT NULL DEFAULT 'OTHER', description text NOT NULL, canonical_url text, provenance jsonb NOT NULL DEFAULT '{}', observed_at timestamptz, strength text NOT NULL DEFAULT 'UNKNOWN', directness text NOT NULL DEFAULT 'UNKNOWN', independence_key text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS claim_evidence(claim_id uuid NOT NULL REFERENCES claims ON DELETE CASCADE, evidence_id uuid NOT NULL REFERENCES evidence ON DELETE CASCADE, relation text NOT NULL CHECK(relation IN ('SUPPORTS','CONTRADICTS','PARTIALLY_SUPPORTS','INCONCLUSIVE')), independence_group text, PRIMARY KEY(claim_id,evidence_id));
CREATE TABLE IF NOT EXISTS contradictions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_a uuid NOT NULL REFERENCES claims ON DELETE CASCADE, claim_b uuid NOT NULL REFERENCES claims ON DELETE CASCADE, type text NOT NULL CHECK(type IN ('OCCURRENCE','ATTRIBUTION','QUANTITATIVE','LOCATION','INTENT','STATUS','CONSEQUENCE')), explanation text NOT NULL, status text NOT NULL DEFAULT 'CONTESTED', created_at timestamptz NOT NULL DEFAULT now(), CHECK(claim_a<>claim_b), UNIQUE(claim_a,claim_b));
CREATE TABLE IF NOT EXISTS entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_name text NOT NULL, type text NOT NULL, aliases text[] NOT NULL DEFAULT '{}', country_code text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(canonical_name,type));
CREATE TABLE IF NOT EXISTS event_entities(event_id uuid REFERENCES event_threads ON DELETE CASCADE, entity_id uuid REFERENCES entities ON DELETE CASCADE, role text NOT NULL, PRIMARY KEY(event_id,entity_id,role));
CREATE TABLE IF NOT EXISTS incident_entities(incident_id uuid REFERENCES incidents ON DELETE CASCADE, entity_id uuid REFERENCES entities ON DELETE CASCADE, role text NOT NULL, PRIMARY KEY(incident_id,entity_id,role));
CREATE TABLE IF NOT EXISTS entity_relationships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_entity_id uuid NOT NULL REFERENCES entities ON DELETE CASCADE, to_entity_id uuid NOT NULL REFERENCES entities ON DELETE CASCADE, relation text NOT NULL, valid_from date, valid_to date, provenance jsonb NOT NULL DEFAULT '{}', CHECK(from_entity_id<>to_entity_id), UNIQUE(from_entity_id,to_entity_id,relation));
CREATE TABLE IF NOT EXISTS historical_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_key text NOT NULL UNIQUE, title text NOT NULL, summary text, started_at date, ended_at date, actors jsonb NOT NULL DEFAULT '[]', outcomes jsonb NOT NULL DEFAULT '{}', sources jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS historical_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), historical_event_id uuid NOT NULL REFERENCES historical_events ON DELETE CASCADE, title text NOT NULL, occurred_at date, details jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS historical_relationships(from_id uuid NOT NULL REFERENCES historical_events ON DELETE CASCADE, to_id uuid NOT NULL REFERENCES historical_events ON DELETE CASCADE, relation text NOT NULL, PRIMARY KEY(from_id,to_id,relation));
CREATE TABLE IF NOT EXISTS historical_topics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text);
CREATE TABLE IF NOT EXISTS historical_event_topics(event_id uuid REFERENCES historical_events ON DELETE CASCADE, topic_id uuid REFERENCES historical_topics ON DELETE CASCADE, PRIMARY KEY(event_id,topic_id));
CREATE TABLE IF NOT EXISTS historical_interpretations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), historical_event_id uuid NOT NULL REFERENCES historical_events, event_thread_id uuid NOT NULL REFERENCES event_threads ON DELETE CASCADE, interpretation text NOT NULL, labels text[] NOT NULL DEFAULT '{}', sources jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(historical_event_id,event_thread_id));
CREATE TABLE IF NOT EXISTS india_exposure_nodes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, domain text NOT NULL CHECK(domain IN ('ENERGY','MARITIME','TRADE','SUPPLY_CHAINS','DEFENCE','STRATEGIC_INTERESTS')), description text, level smallint NOT NULL DEFAULT 0 CHECK(level BETWEEN 0 AND 4), label text NOT NULL DEFAULT 'KNOWN_EXPOSURE' CHECK(label IN ('KNOWN_EXPOSURE','INFERRED_IMPACT','SPECULATIVE_POSSIBILITY')));
CREATE TABLE IF NOT EXISTS india_exposure_edges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_node_id uuid NOT NULL REFERENCES india_exposure_nodes ON DELETE CASCADE, to_node_id uuid NOT NULL REFERENCES india_exposure_nodes ON DELETE CASCADE, pathway text NOT NULL, evidence jsonb NOT NULL DEFAULT '[]', UNIQUE(from_node_id,to_node_id,pathway));
CREATE TABLE IF NOT EXISTS india_variables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, unit text, description text);
CREATE TABLE IF NOT EXISTS india_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variable_id uuid NOT NULL REFERENCES india_variables ON DELETE CASCADE, observed_at timestamptz NOT NULL, value numeric NOT NULL, source_url text, metadata jsonb NOT NULL DEFAULT '{}', UNIQUE(variable_id,observed_at,source_url));
CREATE TABLE IF NOT EXISTS impact_hypotheses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_thread_id uuid NOT NULL REFERENCES event_threads ON DELETE CASCADE, statement text NOT NULL, label text NOT NULL CHECK(label IN ('KNOWN_EXPOSURE','INFERRED_IMPACT','SPECULATIVE_POSSIBILITY')), causal_confidence confidence_level NOT NULL DEFAULT 'UNVERIFIED', explanation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS impact_evidence(hypothesis_id uuid NOT NULL REFERENCES impact_hypotheses ON DELETE CASCADE, evidence_id uuid NOT NULL REFERENCES evidence ON DELETE CASCADE, relation text NOT NULL, PRIMARY KEY(hypothesis_id,evidence_id));
CREATE TABLE IF NOT EXISTS analyses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_thread_id uuid REFERENCES event_threads ON DELETE CASCADE, kind text NOT NULL, question text, answer text NOT NULL, labels jsonb NOT NULL DEFAULT '[]', cache_key text NOT NULL UNIQUE, model text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analysis_sources(analysis_id uuid REFERENCES analyses ON DELETE CASCADE, claim_id uuid REFERENCES claims ON DELETE CASCADE, document_id uuid REFERENCES documents ON DELETE CASCADE, evidence_id uuid REFERENCES evidence ON DELETE CASCADE, PRIMARY KEY(analysis_id,claim_id,document_id,evidence_id));
CREATE TABLE IF NOT EXISTS embeddings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), object_type text NOT NULL, object_id uuid NOT NULL, model text NOT NULL, embedding vector(768) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(object_type,object_id,model));
CREATE INDEX IF NOT EXISTS embeddings_vector_idx ON embeddings USING ivfflat (embedding vector_cosine_ops) WITH (lists=100);
CREATE TABLE IF NOT EXISTS collection_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES sources ON DELETE SET NULL, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, status text NOT NULL DEFAULT 'RUNNING' CHECK(status IN ('RUNNING','SUCCEEDED','PARTIAL','FAILED')), fetched_count integer NOT NULL DEFAULT 0, inserted_count integer NOT NULL DEFAULT 0, skipped_count integer NOT NULL DEFAULT 0, errors jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS event_updates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_thread_id uuid NOT NULL REFERENCES event_threads ON DELETE CASCADE, incident_id uuid REFERENCES incidents ON DELETE SET NULL, change_type text NOT NULL, summary text NOT NULL, material boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watchlists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_thread_id uuid NOT NULL REFERENCES event_threads ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_thread_id));
CREATE INDEX IF NOT EXISTS event_updates_event_time_idx ON event_updates(event_thread_id,created_at DESC);
